{
  "name": "qrypt-aes-generator",
  "version": "1.0.0",
  "description": "Generate an AES-256 key using Qrypt quantum entropy",
  "type": "module",
  "main": "index.js",
  "scripts": {
    "start": "node index.js",
    "test": "node --test"
  },
  "dependencies": {},
  "devDependencies": {},
  "engines": {
    "node": ">=20.12.0"
  }
}

/**
 * Qrypt Quantum Entropy AES-256 Key Generator
 * Fetches quantum entropy from Qrypt API, derives an AES-256 key,
 * and demonstrates AES-256-GCM encryption and decryption.
 */

import crypto from 'node:crypto';
import process from 'node:process';

const QRYPT_API_URL = 'https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1';

export async function fetchQuantumEntropy(apiKey) {
  if (!apiKey) {
    throw new Error('QRYPT_API_KEY is required');
  }

  const response = await fetch(QRYPT_API_URL, {
    method: 'GET',
    headers: {
      'Authorization': <REDACTED> ${apiKey}`,
      'Accept': 'application/json'
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Qrypt API error (${response.status}): ${errorText}`);
  }

  const data = await response.json();
  if (!data.random) {
    throw new Error('Invalid response from Qrypt API: missing "random" field');
  }

  // Base64 encoded entropy string from Qrypt
  return data.random;
}

export function deriveAesKey(base64Entropy) {
  const entropyBuffer = Buffer.from(base64Entropy, 'base64');
  if (entropyBuffer.length < 32) {
    throw new Error(`Insufficient entropy received: expected at least 32 bytes, got ${entropyBuffer.length}`);
  }
  // Take the first 32 bytes (256 bits) for AES-256 key
  return entropyBuffer.subarray(0, 32);
}

export function encryptMessage(key, plaintext) {
  const iv = crypto.randomBytes(12); // 96-bit IV for GCM
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return {
    iv: iv.toString('hex'),
    encryptedData: encrypted,
    authTag: authTag
  };
}

export function decryptMessage(key, encryptedPayload) {
  const iv = Buffer.from(encryptedPayload.iv, 'hex');
  const authTag = Buffer.from(encryptedPayload.authTag, 'hex');
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(authTag);
  let decrypted = decipher.update(encryptedPayload.encryptedData, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

// CLI Execution runner
async function main() {
  const apiKey = process.env.QRYPT_API_KEY;
  if (!apiKey) {
    console.error('Error: QRYPT_API_KEY environment variable is not set.');
    console.error('Please set QRYPT_API_KEY=your_api_key and try again.');
    process.exit(1);
  }

  console.log('Requesting quantum entropy from Qrypt (EUS)...');
  try {
    const base64Entropy = await fetchQuantumEntropy(apiKey);
    console.log('Successfully retrieved quantum entropy.');

    const aesKey = deriveAesKey(base64Entropy);
    console.log(`Derived AES-256 Key (Hex): ${aesKey.toString('hex')} (${aesKey.length * 8} bits)`);

    const sampleMessage = 'Hello, Quantum World with Qrypt!';
    console.log(`\nEncrypting sample message: "${sampleMessage}"`);
    const encrypted = encryptMessage(aesKey, sampleMessage);
    console.log('Encrypted payload:', JSON.stringify(encrypted, null, 2));

    const decrypted = decryptMessage(aesKey, encrypted);
    console.log(`Decrypted message: "${decrypted}"`);
    console.log('\nVerification successful!');
  } catch (err) {
    console.error('Error during Qrypt key generation/encryption:', err.message);
    process.exit(1);
  }
}

// Run main if executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

import test from 'node:test';
import assert from 'node:assert';
import crypto from 'node:crypto';
import { deriveAesKey, encryptMessage, decryptMessage } from './index.js';

test('deriveAesKey extracts 32 bytes (256-bit) correctly from base64 entropy', () => {
  // Generate 64 random bytes, encode to base64
  const randomBytes = crypto.randomBytes(64);
  const base64Entropy = randomBytes.toString('base64');

  const key = deriveAesKey(base64Entropy);
  assert.strictEqual(key.length, 32);
  assert.deepStrictEqual(key, randomBytes.subarray(0, 32));
});

test('deriveAesKey throws on insufficient entropy length', () => {
  const shortBytes = crypto.randomBytes(16);
  const base64Entropy = shortBytes.toString('base64');

  assert.throws(() => {
    deriveAesKey(base64Entropy);
  }, /Insufficient entropy received/);
});

test('encryptMessage and decryptMessage roundtrip successfully', () => {
  const key = crypto.randomBytes(32);
  const message = 'Test Quantum AES-256 Secret Message 🚀';

  const encrypted = encryptMessage(key, message);
  assert.ok(encrypted.iv);
  assert.ok(encrypted.encryptedData);
  assert.ok(encrypted.authTag);

  const decrypted = decryptMessage(key, encrypted);
  assert.strictEqual(decrypted, message);
});
